(function () {
  function safeParse(id) {
    var el = document.getElementById(id);
    if (!el) return null;
    try {
      return JSON.parse(el.textContent || el.innerText || 'null');
    } catch (e) {
      return null;
    }
  }

  var userConfig = safeParse('swagger-config') || {};
  var oauthConfig = safeParse('swagger-oauth-config');

  var config = {
    dom_id: userConfig.dom_id || '#swagger-ui',
    url: userConfig.url,
    deepLinking: true,
    presets: [SwaggerUIBundle.presets.apis, SwaggerUIStandalonePreset],
    plugins: [SwaggerUIBundle.plugins.DownloadUrl],
    layout: userConfig.layout || 'StandaloneLayout',
  };

  // Merge any other provided options
  for (var k in userConfig) {
    if (Object.prototype.hasOwnProperty.call(userConfig, k)) {
      config[k] = userConfig[k];
    }
  }

  window.onload = function () {
    var ui = SwaggerUIBundle(config);
    if (oauthConfig && ui && ui.initOAuth) {
      ui.initOAuth(oauthConfig);
    }
    window.ui = ui;
  };
})();
